{
  "schemaVersion": "0.2",
  "slug": "skeleton",
  "name": "Skeleton",
  "status": "experimental",
  "purpose": "Placeholder preview for content that is loading.",
  "scenarios": [
    "Show loading card",
    "Show loading list",
    "Show loading text block"
  ],
  "props": {
    "variant": {
      "type": "enum",
      "required": false,
      "description": "Skeleton shape.",
      "values": [
        "text",
        "circle",
        "rectangle"
      ],
      "default": "text"
    },
    "width": {
      "type": "string",
      "required": false,
      "description": "Inline width.",
      "default": "100%"
    },
    "height": {
      "type": "string",
      "required": false,
      "description": "Block height.",
      "default": "1rem"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "variant",
      "values": [
        "text",
        "circle",
        "rectangle"
      ],
      "default": "text",
      "description": "Skeleton shape."
    }
  ],
  "states": [
    {
      "name": "loading",
      "description": "Skeleton is visible."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "page",
      "list"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use skeleton for long indeterminate waits without a label.",
    "Do not set aria-busy on the skeleton itself."
  ],
  "a11y": {
    "role": "status",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "Announced as loading by the parent region.",
    "wcag": [
      "4.1.3"
    ]
  },
  "responsive": {
    "strategy": "Inline-size and block-size are configurable.",
    "breakpoints": {
      "compact": "Respects parent.",
      "medium": "Respects parent.",
      "large": "Respects parent."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "No direction-specific styling.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "skeleton",
    "states": [
      "loading"
    ],
    "intents": [
      "indicate-loading"
    ]
  }
}

import './styles.css'

export interface SkeletonProps {
  variant?: 'text' | 'circle' | 'rectangle'
  width?: string
  height?: string
  className?: string
}

export function Skeleton({ variant = 'text', width = '100%', height = '1rem', className }: SkeletonProps) {
  const classes = ['cu-skeleton', 'cu-skeleton--' + variant, className].filter(Boolean).join(' ')
  const style = { width, height }
  return <div aria-hidden="true" className={classes} data-ai-role="skeleton" data-ai-intent="indicate-loading" data-ai-state="loading" style={style} />
}

.cu-skeleton {
  display: block;
  background: var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
  animation: cu-skeleton-pulse 2s ease-in-out infinite;
}

.cu-skeleton--circle {
  border-radius: 50%;
}

.cu-skeleton--rectangle {
  border-radius: var(--cu-radius-md);
}

@keyframes cu-skeleton-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@media (prefers-reduced-motion: reduce) {
  .cu-skeleton {
    animation: none;
  }
}
